sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float angle;
uniform float mask;
half4 main(float2 coord) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float2 v = coord - size * 0.5;
    float along = dot(v, d);
    half4 color = image.eval(coord + d * (along / max(scale, 0.01) - along));
    if (mask > 0.5) color *= image.eval(coord).a;
    return color;
}
